use serde::Serialize;
#[derive(Serialize)]
struct Reading { name: String, score: u8 }
fn main() -> Result<(), serde_json::Error> {
    let reading = Reading { name: "Ada".into(), score: 10 };
    println!("{}", serde_json::to_string(&reading)?);
    Ok(())
}

