#[derive(Debug, thiserror::Error)]
enum PortError {
    #[error("invalid port")]
    Invalid(#[from] std::num::ParseIntError),
}
fn parse_port(text: &str) -> Result<u16, PortError> {
    Ok(text.parse()?)
}
fn main() {
    match parse_port("bad") {
        Ok(port) => println!("{port}"),
        Err(error) => println!("{error}"),
    }
}

use anyhow::Context;
fn load_port(text: &str) -> anyhow::Result<u16> {
    let port = text.parse::<u16>().context("port must be a number")?;
    anyhow::ensure!(port != 0, "port must be non-zero");
    Ok(port)
}
